import{_ as s,a as o,c as a,ac as n}from"./chunks/framework.BSuaGltH.js";const d=JSON.parse('{"title":"第四册：流利英语 · 全册短语与句型 · 第1–24课","description":"按课次汇总短语用法与原创句型，链接对应课时。","frontmatter":{"title":"第四册：流利英语 · 全册短语与句型 · 第1–24课","description":"按课次汇总短语用法与原创句型，链接对应课时。","splitFrom":"life/english/new-concept/book-4/phrases.md","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"句法与表达查阅","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"第四册：流利英语 · 全册短语与句型","summary":"按课次汇总短语用法与原创句型，链接对应课时。","status":"active","related":[{"title":"程序员英语 01：学习路线与能力自测","link":"/life/english/programmer/overview","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 02：技术词汇与句子骨架","link":"/life/english/programmer/vocabulary","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 03：读懂文档中的条件与约束","link":"/life/english/programmer/reading-docs","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 04：读报错、搜索与求助","link":"/life/english/programmer/errors-search","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 05：写 Issue、Commit 与 PR","link":"/life/english/programmer/issue-pr","kind":"路线与能力起点","scope":"general","audience":"general"}],"prev":{"text":"第四册：流利英语 · 全册短语与句型","link":"/life/english/new-concept/book-4/phrases"},"next":{"text":"第四册：流利英语 · 全册短语与句型 · 第25–48课","link":"/life/english/new-concept/book-4/phrases-part-02"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第四册：流利英语 · 全册短语与句型","link":"/life/english/new-concept/book-4/phrases"},"next":{"text":"第四册：流利英语 · 全册短语与句型 · 第25–48课","link":"/life/english/new-concept/book-4/phrases-part-02"}},"headers":[],"relativePath":"life/english/new-concept/book-4/phrases-part-01.md","filePath":"life/english/new-concept/book-4/phrases-part-01.md"}'),t={name:"life/english/new-concept/book-4/phrases-part-01.md"};function l(i,e,r,h,c,p){return o(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="第四册-流利英语-·-全册短语与句型-·-第1–24课" tabindex="-1">第四册：流利英语 · 全册短语与句型 · 第1–24课 <a class="header-anchor" href="#第四册-流利英语-·-全册短语与句型-·-第1–24课" aria-label="Permalink to &quot;第四册：流利英语 · 全册短语与句型 · 第1–24课&quot;">​</a></h1><p><a href="/life/english/new-concept/book-4/phrases">返回分篇目录</a></p><p><a href="/life/english/new-concept/book-4/overview">本册介绍</a> · <a href="/life/english/new-concept/book-4/contents">全册课程目录</a> · <a href="/life/english/new-concept/book-4/grammar">全册语法总结</a> · <a href="/life/english/new-concept/book-4/vocabulary">全册单词总结</a> · <a href="/life/english/new-concept/book-4/phrases">全册短语与句型</a> · <a href="/life/english/new-concept/book-4/mistakes">全册易错点</a> · <a href="/life/english/new-concept/book-4/review">综合复习与自测</a></p><h2 id="第四册-流利英语-·-全册短语与句型" tabindex="-1">第四册：流利英语 · 全册短语与句型 <a class="header-anchor" href="#第四册-流利英语-·-全册短语与句型" aria-label="Permalink to &quot;第四册：流利英语 · 全册短语与句型 {#第四册-流利英语-·-全册短语与句型}&quot;">​</a></h2><p><a href="/life/english/new-concept/book-4/overview">本册介绍</a> · <a href="/life/english/new-concept/book-4/contents">全册课程目录</a> · <a href="/life/english/new-concept/book-4/grammar">全册语法总结</a> · <a href="/life/english/new-concept/book-4/vocabulary">全册单词总结</a> · <a href="/life/english/new-concept/book-4/phrases">全册短语与句型</a> · <a href="/life/english/new-concept/book-4/mistakes">全册易错点</a> · <a href="/life/english/new-concept/book-4/review">综合复习与自测</a></p><h2 id="lesson-1-·-推测情态动词与过去事件" tabindex="-1">Lesson 1 · 推测情态动词与过去事件 <a class="header-anchor" href="#lesson-1-·-推测情态动词与过去事件" aria-label="Permalink to &quot;Lesson 1 · 推测情态动词与过去事件 {#lesson-1-·-推测情态动词与过去事件}&quot;">​</a></h2><ul><li>date back to — 追溯到，通常用现在时说明年代</li><li>in the absence of — 在缺乏某条件时</li></ul><p><strong>句型示范：</strong> The marks might have been made by tools, but their origin remains uncertain.</p><p>might have been made 是情态动词加完成时被动结构；but 连接推测与限制；their 指 marks。</p><p><a href="/life/english/new-concept/book-4/unit-01/lesson-001">进入本课</a></p><h2 id="lesson-2-·-数量词与可数性" tabindex="-1">Lesson 2 · 数量词与可数性 <a class="header-anchor" href="#lesson-2-·-数量词与可数性" aria-label="Permalink to &quot;Lesson 2 · 数量词与可数性 {#lesson-2-·-数量词与可数性}&quot;">​</a></h2><ul><li>feed on — 以某物为食</li><li>play a role in — 在某过程中起作用</li></ul><p><strong>句型示范：</strong> The number of insects was lower in the sheltered garden.</p><p>主语中心词是 number，因此用 was；of insects 限定数量的对象，lower 是表语。</p><p><a href="/life/english/new-concept/book-4/unit-01/lesson-002">进入本课</a></p><h2 id="lesson-3-·-used-to、would-与过去状态" tabindex="-1">Lesson 3 · used to、would 与过去状态 <a class="header-anchor" href="#lesson-3-·-used-to、would-与过去状态" aria-label="Permalink to &quot;Lesson 3 · used to、would 与过去状态 {#lesson-3-·-used-to、would-与过去状态}&quot;">​</a></h2><ul><li>make a living — 谋生</li><li>set out — 出发，常与时间或目的搭配</li></ul><p><strong>句型示范：</strong> The village used to be quiet, but each summer guides would welcome new climbers.</p><p>used to be 表过去状态；each summer 为 would welcome 建立反复行为的时间框架。</p><p><a href="/life/english/new-concept/book-4/unit-01/lesson-003">进入本课</a></p><h2 id="lesson-4-·-报告动词与认知距离" tabindex="-1">Lesson 4 · 报告动词与认知距离 <a class="header-anchor" href="#lesson-4-·-报告动词与认知距离" aria-label="Permalink to &quot;Lesson 4 · 报告动词与认知距离 {#lesson-4-·-报告动词与认知距离}&quot;">​</a></h2><ul><li>be reported to — 据报告，保留消息来源</li><li>rule out — 排除一种可能解释</li></ul><p><strong>句型示范：</strong> The participant was reported to have identified the colour, but the test did not rule out visual cues.</p><p>was reported to 标示二手报告；to have identified 表辨认早于报告；but 引出方法限制。</p><p><a href="/life/english/new-concept/book-4/unit-01/lesson-004">进入本课</a></p><h2 id="lesson-5-·-让步从句与主句重心" tabindex="-1">Lesson 5 · 让步从句与主句重心 <a class="header-anchor" href="#lesson-5-·-让步从句与主句重心" aria-label="Permalink to &quot;Lesson 5 · 让步从句与主句重心 {#lesson-5-·-让步从句与主句重心}&quot;">​</a></h2><ul><li>be open to — 愿意接受</li><li>take seriously — 认真对待</li></ul><p><strong>句型示范：</strong> Although Lena had little experience, the team took her proposal seriously.</p><p>although 从句提供让步背景；主句 took 为一般过去时，her proposal 是宾语。</p><p><a href="/life/english/new-concept/book-4/unit-01/lesson-005">进入本课</a></p><h2 id="lesson-6-·-not-so-much-a-as-b-的纠正性对比" tabindex="-1">Lesson 6 · not so much A as B 的纠正性对比 <a class="header-anchor" href="#lesson-6-·-not-so-much-a-as-b-的纠正性对比" aria-label="Permalink to &quot;Lesson 6 · not so much A as B 的纠正性对比 {#lesson-6-·-not-so-much-a-as-b-的纠正性对比}&quot;">​</a></h2><ul><li>play by the rules — 按规则比赛</li><li>at stake — 处于得失关头</li></ul><p><strong>句型示范：</strong> The argument was not so much about the score as about respect.</p><p>about the score 与 about respect 平行；not so much…as… 将解释重点移向 respect。</p><p><a href="/life/english/new-concept/book-4/unit-01/lesson-006">进入本课</a></p><h2 id="lesson-7-·-关系从句中的指代与功能说明" tabindex="-1">Lesson 7 · 关系从句中的指代与功能说明 <a class="header-anchor" href="#lesson-7-·-关系从句中的指代与功能说明" aria-label="Permalink to &quot;Lesson 7 · 关系从句中的指代与功能说明 {#lesson-7-·-关系从句中的指代与功能说明}&quot;">​</a></h2><ul><li>bounce back — 反射回来</li><li>depend on — 取决于；依靠</li></ul><p><strong>句型示范：</strong> The device measures the delay between a signal and the echo that returns from the wall.</p><p>that returns from the wall 修饰 echo，that 在从句作主语，不能省略。</p><p><a href="/life/english/new-concept/book-4/unit-01/lesson-007">进入本课</a></p><h2 id="lesson-8-·-情态动词的被动结构" tabindex="-1">Lesson 8 · 情态动词的被动结构 <a class="header-anchor" href="#lesson-8-·-情态动词的被动结构" aria-label="Permalink to &quot;Lesson 8 · 情态动词的被动结构 {#lesson-8-·-情态动词的被动结构}&quot;">​</a></h2><ul><li>comply with — 遵守某标准或要求</li><li>fit for purpose — 适合预定用途</li></ul><p><strong>句型示范：</strong> Under our workshop rules, every sample must be checked before it is packed.</p><p>must be checked 是情态被动；before 引导时间从句；under…限定规则的适用范围。</p><p><a href="/life/english/new-concept/book-4/unit-01/lesson-008">进入本课</a></p><h2 id="lesson-9-·-过去完成时与过去叙事参照点" tabindex="-1">Lesson 9 · 过去完成时与过去叙事参照点 <a class="header-anchor" href="#lesson-9-·-过去完成时与过去叙事参照点" aria-label="Permalink to &quot;Lesson 9 · 过去完成时与过去叙事参照点 {#lesson-9-·-过去完成时与过去叙事参照点}&quot;">​</a></h2><ul><li>pass on — 转交信息</li><li>keep track of — 持续掌握动态</li></ul><p><strong>句型示范：</strong> By the time the messenger arrived, the clerk had hidden the letter.</p><p>arrived 是过去参照点；had hidden 表示藏信发生在到达之前；by the time 引出截止时间。</p><p><a href="/life/english/new-concept/book-4/unit-02/lesson-009">进入本课</a></p><h2 id="lesson-10-·-比较结构与范围限定" tabindex="-1">Lesson 10 · 比较结构与范围限定 <a class="header-anchor" href="#lesson-10-·-比较结构与范围限定" aria-label="Permalink to &quot;Lesson 10 · 比较结构与范围限定 {#lesson-10-·-比较结构与范围限定}&quot;">​</a></h2><ul><li>set up — 建立公司或机构</li><li>draw on — 利用已有经验或资源</li></ul><p><strong>句型示范：</strong> Office rents in the new district are lower than those in the city centre.</p><p>those 代替复数 office rents，保持比较对象一致；lower 是比较级表语。</p><p><a href="/life/english/new-concept/book-4/unit-02/lesson-010">进入本课</a></p><h2 id="lesson-11-·-动名词短语作主语" tabindex="-1">Lesson 11 · 动名词短语作主语 <a class="header-anchor" href="#lesson-11-·-动名词短语作主语" aria-label="Permalink to &quot;Lesson 11 · 动名词短语作主语 {#lesson-11-·-动名词短语作主语}&quot;">​</a></h2><ul><li>take an interest in — 对某事产生兴趣</li><li>keep in touch with — 与某人保持联系</li></ul><p><strong>句型示范：</strong> Learning the names of local plants gives Mei a reason to walk outdoors.</p><p>Learning…plants 是完整动名词主语，中心是活动，因此谓语用 gives，而不是受 names 影响用 give。</p><p><a href="/life/english/new-concept/book-4/unit-02/lesson-011">进入本课</a></p><h2 id="lesson-12-·-unless-与条件从句" tabindex="-1">Lesson 12 · unless 与条件从句 <a class="header-anchor" href="#lesson-12-·-unless-与条件从句" aria-label="Permalink to &quot;Lesson 12 · unless 与条件从句 {#lesson-12-·-unless-与条件从句}&quot;">​</a></h2><ul><li>subject to — 以满足某条件为前提</li><li>in writing — 以书面形式</li></ul><p><strong>句型示范：</strong> In this exercise, the request will remain pending unless the customer signs the form.</p><p>unless 引出例外条件；signs 用现在时表未来条件；主句 will remain 表结果。</p><p><a href="/life/english/new-concept/book-4/unit-02/lesson-012">进入本课</a></p><h2 id="lesson-13-·-目的不定式与-so-that" tabindex="-1">Lesson 13 · 目的不定式与 so that <a class="header-anchor" href="#lesson-13-·-目的不定式与-so-that" aria-label="Permalink to &quot;Lesson 13 · 目的不定式与 so that {#lesson-13-·-目的不定式与-so-that}&quot;">​</a></h2><ul><li>carry out — 执行调查或实验</li><li>in search of — 寻找</li></ul><p><strong>句型示范：</strong> The team collected rock samples so that specialists could compare the layers.</p><p>so that 从句有独立主语 specialists，与主句 team 不同；could compare 表当时的目的。</p><p><a href="/life/english/new-concept/book-4/unit-02/lesson-013">进入本课</a></p><h2 id="lesson-14-·-第二条件句与假设距离" tabindex="-1">Lesson 14 · 第二条件句与假设距离 <a class="header-anchor" href="#lesson-14-·-第二条件句与假设距离" aria-label="Permalink to &quot;Lesson 14 · 第二条件句与假设距离 {#lesson-14-·-第二条件句与假设距离}&quot;">​</a></h2><ul><li>result in — 导致某结果</li><li>over time — 随着时间推移</li></ul><p><strong>句型示范：</strong> If we changed the starting value slightly, the two simulations might diverge over time.</p><p>changed 在条件句表假设；might diverge 保留结果不确定性；over time 表渐进过程。</p><p><a href="/life/english/new-concept/book-4/unit-02/lesson-014">进入本课</a></p><h2 id="lesson-15-·-whether-引导名词性从句" tabindex="-1">Lesson 15 · whether 引导名词性从句 <a class="header-anchor" href="#lesson-15-·-whether-引导名词性从句" aria-label="Permalink to &quot;Lesson 15 · whether 引导名词性从句 {#lesson-15-·-whether-引导名词性从句}&quot;">​</a></h2><ul><li>keep confidential — 保密</li><li>weigh up — 权衡因素</li></ul><p><strong>句型示范：</strong> The team must decide whether the preliminary data can be shared with partners.</p><p>whether 从句作 decide 的宾语；the preliminary data 在 can 前，保持陈述语序。</p><p><a href="/life/english/new-concept/book-4/unit-02/lesson-015">进入本课</a></p><h2 id="lesson-16-·-so-that-与-such-that-的结果表达" tabindex="-1">Lesson 16 · so…that 与 such…that 的结果表达 <a class="header-anchor" href="#lesson-16-·-so-that-与-such-that-的结果表达" aria-label="Permalink to &quot;Lesson 16 · so…that 与 such…that 的结果表达 {#lesson-16-·-so-that-与-such-that-的结果表达}&quot;">​</a></h2><ul><li>within walking distance — 在步行可达范围内</li><li>make room for — 为某物腾出空间</li></ul><p><strong>句型示范：</strong> The crossing was so far away that several residents asked for a nearer one.</p><p>so 修饰形容词短语 far away；that 从句给出结果；one 指 crossing。</p><p><a href="/life/english/new-concept/book-4/unit-02/lesson-016">进入本课</a></p><h2 id="lesson-17-·-cause、lead-to-与-be-associated-with" tabindex="-1">Lesson 17 · cause、lead to 与 be associated with <a class="header-anchor" href="#lesson-17-·-cause、lead-to-与-be-associated-with" aria-label="Permalink to &quot;Lesson 17 · cause、lead to 与 be associated with {#lesson-17-·-cause、lead-to-与-be-associated-with}&quot;">​</a></h2><ul><li>be associated with — 与某现象相关</li><li>account for — 解释；占某比例</li></ul><p><strong>句型示范：</strong> In the fictional survey, a wetter spring was associated with fewer rabbits near the field.</p><p>was associated with 只说明关联；In the fictional survey 限定为练习数据，未确认兔子减少的原因。</p><p><a href="/life/english/new-concept/book-4/unit-03/lesson-017">进入本课</a></p><h2 id="lesson-18-·-感官动词的主动与被动转换" tabindex="-1">Lesson 18 · 感官动词的主动与被动转换 <a class="header-anchor" href="#lesson-18-·-感官动词的主动与被动转换" aria-label="Permalink to &quot;Lesson 18 · 感官动词的主动与被动转换 {#lesson-18-·-感官动词的主动与被动转换}&quot;">​</a></h2><ul><li>come to the surface — 浮到水面</li><li>on the basis of — 根据某项证据</li></ul><p><strong>句型示范：</strong> The animal was seen to surface beside the boat twice.</p><p>was seen to surface 是感官动词被动结构；twice 表完整动作出现两次，没有说明动作意图。</p><p><a href="/life/english/new-concept/book-4/unit-03/lesson-018">进入本课</a></p><h2 id="lesson-19-·-同位语从句与定语从句" tabindex="-1">Lesson 19 · 同位语从句与定语从句 <a class="header-anchor" href="#lesson-19-·-同位语从句与定语从句" aria-label="Permalink to &quot;Lesson 19 · 同位语从句与定语从句 {#lesson-19-·-同位语从句与定语从句}&quot;">​</a></h2><ul><li>make sense of — 理解零散材料</li><li>be based on — 以某材料为依据</li></ul><p><strong>句型示范：</strong> The belief that every dream has one fixed meaning is difficult to justify.</p><p>that…meaning 说明 belief 的内容，内部主语 every dream、谓语 has、宾语 meaning 完整。</p><p><a href="/life/english/new-concept/book-4/unit-03/lesson-019">进入本课</a></p><h2 id="lesson-20-·-过去分词作后置定语" tabindex="-1">Lesson 20 · 过去分词作后置定语 <a class="header-anchor" href="#lesson-20-·-过去分词作后置定语" aria-label="Permalink to &quot;Lesson 20 · 过去分词作后置定语 {#lesson-20-·-过去分词作后置定语}&quot;">​</a></h2><ul><li>consist of — 由若干部分组成</li><li>under controlled conditions — 在受控条件下</li></ul><p><strong>句型示范：</strong> The samples collected on Tuesday were analysed separately.</p><p>collected on Tuesday 后置修饰 samples，相当于 that were collected；were analysed 是全句谓语。</p><p><a href="/life/english/new-concept/book-4/unit-03/lesson-020">进入本课</a></p><h2 id="lesson-21-·-it-is-was-that-强调句" tabindex="-1">Lesson 21 · It is/was…that 强调句 <a class="header-anchor" href="#lesson-21-·-it-is-was-that-强调句" aria-label="Permalink to &quot;Lesson 21 · It is/was…that 强调句 {#lesson-21-·-it-is-was-that-强调句}&quot;">​</a></h2><ul><li>on screen — 在银幕上</li><li>be shaped by — 受到某因素塑造</li></ul><p><strong>句型示范：</strong> It was the actor’s silence that made the final scene so tense.</p><p>the actor’s silence 是被强调主语；还原为 The actor’s silence made the final scene so tense。</p><p><a href="/life/english/new-concept/book-4/unit-03/lesson-021">进入本课</a></p><h2 id="lesson-22-·-what-从句作主语与表语" tabindex="-1">Lesson 22 · what 从句作主语与表语 <a class="header-anchor" href="#lesson-22-·-what-从句作主语与表语" aria-label="Permalink to &quot;Lesson 22 · what 从句作主语与表语 {#lesson-22-·-what-从句作主语与表语}&quot;">​</a></h2><ul><li>put into practice — 付诸实践</li><li>for the benefit of — 为了某人的利益</li></ul><p><strong>句型示范：</strong> What matters is whether the new tool solves a real problem.</p><p>What matters 为主语从句；whether…problem 为表语从句，说明评判内容。</p><p><a href="/life/english/new-concept/book-4/unit-03/lesson-022">进入本课</a></p><h2 id="lesson-23-·-现在分词状语与逻辑主语" tabindex="-1">Lesson 23 · 现在分词状语与逻辑主语 <a class="header-anchor" href="#lesson-23-·-现在分词状语与逻辑主语" aria-label="Permalink to &quot;Lesson 23 · 现在分词状语与逻辑主语 {#lesson-23-·-现在分词状语与逻辑主语}&quot;">​</a></h2><ul><li>take advantage of — 利用有利条件</li><li>change direction — 改变方向</li></ul><p><strong>句型示范：</strong> Gliding above the field, the bird turned towards the hills.</p><p>Gliding… 为伴随分词状语，逻辑主语为 the bird，与 turned 的主语一致。</p><p><a href="/life/english/new-concept/book-4/unit-03/lesson-023">进入本课</a></p><h2 id="lesson-24-·-否定或限制副词前置倒装" tabindex="-1">Lesson 24 · 否定或限制副词前置倒装 <a class="header-anchor" href="#lesson-24-·-否定或限制副词前置倒装" aria-label="Permalink to &quot;Lesson 24 · 否定或限制副词前置倒装 {#lesson-24-·-否定或限制副词前置倒装}&quot;">​</a></h2><ul><li>appeal to — 吸引某人</li><li>in the eye of — 从某人的眼光来看</li></ul><p><strong>句型示范：</strong> Rarely do two viewers notice exactly the same details in a painting.</p><p>Rarely 前置触发 do two viewers 的部分倒装；notice 保持原形；不是把整句完全颠倒。</p><p><a href="/life/english/new-concept/book-4/unit-03/lesson-024">进入本课</a></p>',125)])])}const f=s(t,[["render",l]]);export{d as __pageData,f as default};
